package com.example.starter.calibration.repo;

import java.sql.PreparedStatement;
import java.sql.Statement;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;

import com.example.starter.calibration.model.Measurement;
import com.example.starter.calibration.model.MeasurementStatus;

/**
 * 测量记录持久化。measurement_key 全局唯一作为幂等键；状态流转由放行事务在行锁内完成。
 * 已配置分辨率格点的仪器在提交时冻结配置版本、原点、步长、k 与量化值。
 */
@Repository
public class MeasurementRepository {

    private static final RowMapper<Measurement> MAPPER = (rs, rowNum) -> new Measurement(
            rs.getLong("id"),
            rs.getString("measurement_key"),
            rs.getString("instrument_id"),
            JdbcTimes.fromDb(rs.getObject("measured_at", LocalDateTime.class)),
            rs.getBigDecimal("raw_reading"),
            rs.getBigDecimal("lower_limit"),
            rs.getBigDecimal("upper_limit"),
            rs.getString("submitted_by"),
            rs.getLong("certificate_id"),
            rs.getBigDecimal("computed_value"),
            rs.getBoolean("passed"),
            MeasurementStatus.valueOf(rs.getString("status")),
            (Integer) rs.getObject("resolution_version"),
            rs.getBigDecimal("grid_origin"),
            rs.getBigDecimal("grid_step"),
            rs.getBigDecimal("grid_k"),
            rs.getBigDecimal("quantized_value"),
            JdbcTimes.fromDb(rs.getObject("created_at", LocalDateTime.class)));

    private final JdbcTemplate jdbc;

    public MeasurementRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 插入测量记录并返回生成的 ID；measurement_key 冲突时抛出 DuplicateKeyException。
     */
    public long insert(Measurement measurement) {
        KeyHolder keyHolder = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO measurement "
                            + "(measurement_key, instrument_id, measured_at, raw_reading, lower_limit, upper_limit, "
                            + "submitted_by, certificate_id, computed_value, passed, status, "
                            + "resolution_version, grid_origin, grid_step, grid_k, quantized_value, created_at) "
                            + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    Statement.RETURN_GENERATED_KEYS);
            ps.setString(1, measurement.measurementKey());
            ps.setString(2, measurement.instrumentId());
            ps.setObject(3, JdbcTimes.toDb(measurement.measuredAt()));
            ps.setBigDecimal(4, measurement.rawReading());
            ps.setBigDecimal(5, measurement.lowerLimit());
            ps.setBigDecimal(6, measurement.upperLimit());
            ps.setString(7, measurement.submittedBy());
            ps.setLong(8, measurement.certificateId());
            ps.setBigDecimal(9, measurement.computedValue());
            ps.setBoolean(10, measurement.passed());
            ps.setString(11, measurement.status().name());
            if (measurement.resolutionVersion() == null) {
                ps.setNull(12, java.sql.Types.INTEGER);
            } else {
                ps.setInt(12, measurement.resolutionVersion());
            }
            ps.setBigDecimal(13, measurement.gridOrigin());
            ps.setBigDecimal(14, measurement.gridStep());
            ps.setBigDecimal(15, measurement.gridK());
            ps.setBigDecimal(16, measurement.quantizedValue());
            ps.setObject(17, JdbcTimes.toDb(measurement.createdAt()));
            return ps;
        }, keyHolder);
        return keyHolder.getKey().longValue();
    }

    /**
     * 按测量键查询（不加锁）。
     */
    public Optional<Measurement> findByKey(String key) {
        return jdbc.query("SELECT * FROM measurement WHERE measurement_key = ?", MAPPER, key)
                .stream().findFirst();
    }

    /**
     * 按测量键查询并加行锁（须在事务内调用），用于放行时串行化状态流转。
     */
    public Optional<Measurement> findByKeyForUpdate(String key) {
        return jdbc.query("SELECT * FROM measurement WHERE measurement_key = ? FOR UPDATE", MAPPER, key)
                .stream().findFirst();
    }

    /**
     * 将测量记录置为已放行（须在持有行锁的事务内调用）。
     */
    public void markReleased(long id) {
        jdbc.update("UPDATE measurement SET status = ? WHERE id = ?",
                MeasurementStatus.RELEASED.name(), id);
    }

    /**
     * 查询当前可用结果：已放行且证书未撤销。instrumentId 为 null 时不过滤仪器。
     */
    public List<Measurement> findUsable(String instrumentId) {
        String base = "SELECT m.* FROM measurement m "
                + "JOIN calibration_certificate c ON c.id = m.certificate_id "
                + "WHERE m.status = 'RELEASED' AND c.revoked = FALSE ";
        if (instrumentId == null) {
            return jdbc.query(base + "ORDER BY m.id", MAPPER);
        }
        return jdbc.query(base + "AND m.instrument_id = ? ORDER BY m.id", MAPPER, instrumentId);
    }
}

package com.example.starter.calibration.repo;

import java.math.BigDecimal;
import java.time.Instant;
import java.time.LocalDateTime;
import java.util.Optional;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import com.example.starter.calibration.model.ResolutionConfig;

/**
 * 仪器分辨率格点配置持久化。每台仪器一行当前配置；
 * 更新按 expectedVersion 条件更新实现乐观并发，不换版回算既有测量。
 */
@Repository
public class ResolutionRepository {

    private static final RowMapper<ResolutionConfig> MAPPER = (rs, rowNum) -> new ResolutionConfig(
            rs.getString("instrument_id"),
            rs.getInt("version"),
            rs.getBigDecimal("grid_origin"),
            rs.getBigDecimal("grid_step"),
            rs.getString("updated_by"),
            JdbcTimes.fromDb(rs.getObject("updated_at", LocalDateTime.class)));

    private final JdbcTemplate jdbc;

    public ResolutionRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 按仪器查询当前配置（不加锁）。
     */
    public Optional<ResolutionConfig> findByInstrument(String instrumentId) {
        return jdbc.query("SELECT * FROM instrument_resolution WHERE instrument_id = ?",
                MAPPER, instrumentId).stream().findFirst();
    }

    /**
     * 按仪器查询当前配置并加行锁（须在事务内调用），使提交测量与配置更新串行化。
     */
    public Optional<ResolutionConfig> findByInstrumentForUpdate(String instrumentId) {
        return jdbc.query("SELECT * FROM instrument_resolution WHERE instrument_id = ? FOR UPDATE",
                MAPPER, instrumentId).stream().findFirst();
    }

    /**
     * 新建配置，版本固定为 1；仪器已存在配置时抛出 DuplicateKeyException。
     */
    public void insert(String instrumentId, BigDecimal origin, BigDecimal step,
                       String updatedBy, Instant updatedAt) {
        jdbc.update("INSERT INTO instrument_resolution "
                        + "(instrument_id, version, grid_origin, grid_step, updated_by, updated_at) "
                        + "VALUES (?, 1, ?, ?, ?, ?)",
                instrumentId, origin, step, updatedBy, JdbcTimes.toDb(updatedAt));
    }

    /**
     * 按期望版本条件更新：仅当当前版本等于 expectedVersion 时生效，版本加 1。
     *
     * @return 实际更新行数；0 表示版本冲突或配置不存在
     */
    public int updateWithVersion(String instrumentId, int expectedVersion,
                                 BigDecimal origin, BigDecimal step,
                                 String updatedBy, Instant updatedAt) {
        return jdbc.update("UPDATE instrument_resolution "
                        + "SET version = version + 1, grid_origin = ?, grid_step = ?, "
                        + "updated_by = ?, updated_at = ? "
                        + "WHERE instrument_id = ? AND version = ?",
                origin, step, updatedBy, JdbcTimes.toDb(updatedAt), instrumentId, expectedVersion);
    }
}

