```java
@Service
public class ResolutionService {
    static final String OPERATION = "UPSERT_RESOLUTION";

    // deps: ResolutionRepository, IdempotencyRepository, ObjectMapper

    @Transactional
    public StoredResponse upsert(String instrumentId, UpsertResolutionRequest request, String actor) {
        String op = Inputs.requireText(actor, "X-Actor-Id");
        String resource = Inputs.requireText(instrumentId, "instrumentId");
        String requestId = Inputs.requireText(request.requestId(), "requestId");
        BigDecimal origin = Inputs.requireDecimal(request.origin(), "origin");
        BigDecimal step = Inputs.requireDecimal(request.step(), "step");
        if (step.compareTo(BigDecimal.ZERO) <= 0) throw badRequest("step 必须为正数");
        Integer expectedVersion = request.expectedVersion();
        if (expectedVersion != null && expectedVersion < 1) throw badRequest(...);

        String paramsJson = buildParams(origin, step, expectedVersion); // structured JSON

        var existing = idempotency.findByRequestId(requestId);
        if (existing.isPresent()) return replayOrConflict(existing.get(), actor, resource, paramsJson);

        // business
        ResolutionConfig result;
        int status;
        if (expectedVersion == null) {
            try { resolutions.insert(...); } catch (DuplicateKeyException e) { throw conflict("RESOLUTION_ALREADY_EXISTS", ...); }
            status = 201;
        } else {
            // config must exist
            if (resolutions.findByInstrument(resource).isEmpty()) throw notFound? or 409?
            int updated = resolutions.updateWithVersion(...);
            if (updated == 0) throw conflict("VERSION_CONFLICT", ...);
            status = 200;
        }
        ResolutionConfig saved = resolutions.findByInstrument(resource).orElseThrow();
        ResolutionResponse body = DtoMapper.toResponse(saved);
        String responseJson = objectMapper.writeValueAsString(body);
        try {
            idempotency.insert(new IdempotencyRecord(requestId, OPERATION, op, resource, paramsJson, responseJson, status, Instant.now()));
        } catch (DuplicateKeyException ex) {
            // 并发同键：重新读取已提交记录，重放或 409，不泄露唯一键异常
            ... but we're inside a transaction; the competing record may not be committed yet → the insert would block until the other tx commits (row lock on PK). In H2/MySQL, insert with duplicate PK blocks until other transaction commits/rolls back, then throws DuplicateKeyException. After catch, findByRequestId in same tx — our transaction may be in aborted state? In H2, after a constraint violation the statement fails but transaction can continue (unlike PostgreSQL). Spring's DuplicateKeyException doesn't mark rollback-only automatically (that happens in @Transactional only when exception propagates). So we can re-read. But careful: if the competing transaction committed, our re-read sees it (READ_COMMITTED). OK.
            IdempotencyRecord committed = idempotency.findByRequestId(requestId).orElseThrow(...);
            // But our business write (resolution insert/update) already happened in this tx! If we replay the other's response, our own business write would commit too → double effect. Problem!
        }
